<?php
$verification=$verification??[];$profile=$verification['profile']??[];$submission=$verification['submission']??null;$documents=$verification['documents']??[];$status=$verification['status']??'not_started';
$labels=['not_started'=>'Not Started','draft'=>'Draft','submitted'=>'Submitted','in_review'=>'Under Review','verified'=>'Verified','rejected'=>'Rejected','resubmission_required'=>'Action Required'];
$descriptions=['not_started'=>'Complete your profile and add sample documents to prepare a demo verification submission.','draft'=>'Your demo application is saved as a draft. You can replace its files before submission.','submitted'=>'Your demo verification submission has been received and is awaiting review.','in_review'=>'Your demo verification submission is under review.','verified'=>'Demo Verification Complete. This is a demonstration status only.','rejected'=>'Verification Not Approved. Review the message below and update your application.','resubmission_required'=>'Action Required. Replace the requested information or document, then resubmit.'];
$locked=in_array($status,['submitted','in_review'],true);$docsLocked=in_array($status,['submitted','in_review','verified'],true);$profileFields=['first_name'=>'First Name','last_name'=>'Last Name','phone'=>'Phone','date_of_birth'=>'Date of Birth','country'=>'Country','nationality'=>'Nationality','address_line_1'=>'Residential Address','address_line_2'=>'Address Line 2 (optional)','city'=>'City','state_region'=>'State / Province (optional)','postal_code'=>'Postal Code (optional)'];
$identityTypes=['passport'=>'Passport','national_id'=>'National Identity Card','driver_licence'=>'Driving Licence'];$addressTypes=['utility_bill'=>'Utility Bill','bank_statement'=>'Bank Statement','government_letter'=>'Government Letter','other'=>'Other Approved Demo Document'];
$formatBytes=static fn($n)=>number_format((int)$n/1048576,2).' MB';$docsByCategory=['identity'=>[],'proof_of_address'=>[]];foreach($documents as $document)$docsByCategory[$document['document_category']][]=$document;
