<section class="client-page-intro verification-intro"><div><span class="client-eyebrow">DEMO IDENTITY VERIFICATION</span><h1>Identity Verification</h1><p>A demonstration workflow for completing your MultiForex demo profile.</p></div><span class="client-status-pill is-<?=e($status)?>"><?=e($labels[$status]??'Not Started')?></span></section>
<div class="kyc-disclosure" role="note"><strong>Demo Identity Verification</strong><span>This workflow is provided for demonstration purposes within the MultiForex demo platform. Please do not upload real identity documents. No government or regulator verification is performed.</span></div>
<section class="client-panel kyc-status-panel"><div><span class="client-eyebrow">CURRENT STATUS</span><h2><?=e($labels[$status]??'Not Started')?></h2><p><?=e($descriptions[$status]??$descriptions['not_started'])?></p></div><?php if($submission): ?><dl><div><dt>Submission Reference</dt><dd><?=e($submission['submission_reference']??'—')?></dd></div><div><dt>Account Holder</dt><dd><?=e(trim(($profile['first_name']??'').' '.($profile['last_name']??'')))?></dd></div><div><dt>Submitted</dt><dd><?=e($submission['submitted_at']??'Not submitted')?></dd></div><div><dt>Last Updated</dt><dd><?=e($submission['updated_at']??'—')?></dd></div></dl><?php endif; ?><?php if(!empty($submission['reviewer_message'])||!empty($submission['rejection_reason'])): ?><p class="kyc-review-message"><strong>Reviewer message:</strong> <?=e($submission['reviewer_message']?:$submission['rejection_reason'])?></p><?php endif; ?><?php if(($status==='resubmission_required')&&!empty($submission['resubmission_category'])): ?><p class="kyc-review-message"><strong>Requested update:</strong> <?=e(ucwords(str_replace('_',' ',$submission['resubmission_category'])))?></p><?php endif; ?></section>
<nav class="kyc-steps" aria-label="Verification steps"><span class="is-current"><b>1</b>Personal information</span><span><b>2</b>Identity document</span><span><b>3</b>Proof of address</span><span><b>4</b>Review &amp; submit</span><span><b>5</b>Status</span></nav>
<section class="client-panel"><div class="client-section-heading"><div><h2>Personal Information</h2><p>Account email: <?=e($profile['email']??'—')?> · Email changes use account security settings.</p></div></div>
<form method="post" action="<?=e(site_url('api/verification/profile'))?>" class="kyc-form-grid" data-kyc-ajax><?=csrf_field()?><?php foreach($profileFields as $key=>$label): ?><label class="kyc-field<?=in_array($key,['address_line_1','address_line_2'],true)?' is-wide':''?>"><?=e($label)?><?php if(in_array($key,['country','nationality'],true)): ?><select name="<?=e($key)?>" <?=($locked?'disabled':'')?>><option value="">Choose country</option><?php foreach($countryOptions as $code=>$country): ?><option value="<?=e($code)?>" <?=strtoupper((string)($profile[$key]??''))===$code?'selected':''?>><?=e($country)?></option><?php endforeach; ?></select><?php else: ?><input name="<?=e($key)?>" type="<?= $key==='date_of_birth'?'date':'text' ?>" value="<?=e($profile[$key]??'')?>" maxlength="<?=in_array($key,['first_name','last_name'],true)?'100':'190'?>" <?=($locked?'readonly':'')?> <?=in_array($key,['first_name','last_name','phone','date_of_birth','country','nationality','address_line_1','city'],true)?'required':''?>><?php endif; ?></label><?php endforeach; ?><input type="hidden" name="email" value="<?=e($profile['email']??'')?>"><div class="kyc-form-actions is-wide"><button class="client-button client-button-primary" type="submit" <?=($locked?'disabled':'')?>>Save Profile Draft</button><span data-kyc-message role="status"></span></div></form></section>
<div class="kyc-document-grid">
<?php foreach([['identity','Identity Document',$identityTypes],['proof_of_address','Proof of Address',$addressTypes]] as [$category,$heading,$types]): ?><section class="client-panel"><div class="client-section-heading"><div><h2><?=e($heading)?></h2><p>PDF, JPEG, or PNG · max <?=e((string)round((int)config('KYC_MAX_FILE_SIZE',5242880)/1048576))?> MB</p></div></div><?php if(!empty($docsByCategory[$category])): ?><ul class="kyc-document-list"><?php foreach($docsByCategory[$category] as $doc): ?><li><span class="kyc-file-icon" aria-hidden="true"><?=e(strtoupper(pathinfo($doc['original_filename'],PATHINFO_EXTENSION)))?></span><span class="kyc-file-copy"><strong><?=e($doc['original_filename'])?></strong><small><?=e($types[$doc['document_type']]??'Document')?> · <?=e($formatBytes($doc['file_size']))?> · <?=e(ucfirst($doc['status']))?></small></span><a class="client-text-link" href="<?=e(site_url('client/verification/document?ref='.rawurlencode($doc['document_reference'])))?>">Download</a><?php if(!$docsLocked&&$doc['status']!=='superseded'): ?><form action="<?=e(site_url('api/verification/documents/remove'))?>" method="post" data-kyc-ajax><?=csrf_field()?><input type="hidden" name="document_reference" value="<?=e($doc['document_reference'])?>"><button class="client-text-link" type="submit">Replace</button></form><?php endif; ?></li><?php endforeach; ?></ul><?php endif; ?><form action="<?=e(site_url('api/verification/documents'))?>" method="post" enctype="multipart/form-data" class="kyc-upload-form" data-kyc-ajax><?=csrf_field()?><input type="hidden" name="category" value="<?=e($category)?>"><label>Document type<select name="document_type" required <?=($docsLocked?'disabled':'')?>><option value="">Choose type</option><?php foreach($types as $value=>$label): ?><option value="<?=e($value)?>"><?=e($label)?></option><?php endforeach; ?></select></label><label class="kyc-file-picker">Choose a sample file<input type="file" name="document" accept=".pdf,.jpg,.jpeg,.png,application/pdf,image/jpeg,image/png" required <?=($docsLocked?'disabled':'')?>><small data-kyc-file-name>No file selected</small></label><button class="client-button client-button-secondary" type="submit" <?=($docsLocked?'disabled':'')?>>Upload Demo Document</button><span data-kyc-message role="status"></span></form></section><?php endforeach; ?></div>
